using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Research Agent – uses an LLM with web-search and note-taking tools to
// research a topic, then produce a summary of its findings.
// ---------------------------------------------------------------------------

// --- Tool implementations ---------------------------------------------------

/// <summary>Tools the research agent can invoke during its investigation.</summary>
static class ResearchTools
{
    private static readonly List<string> s_notes = [];
    private static readonly HttpClient s_http = new();

    /// <summary>Search the web for a query and return a JSON array of results.</summary>
    [Description("Search the web for a query. Returns a JSON array of results with title, url, and snippet.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use DuckDuckGo instant-answer API (no key required).
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await s_http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<object>();

            // Abstract / main answer
            var abs = root.GetProperty("Abstract").GetString();
            var absUrl = root.GetProperty("AbstractURL").GetString();
            var absSrc = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrWhiteSpace(abs))
            {
                results.Add(new { title = absSrc ?? "Summary", url = absUrl ?? "", snippet = abs });
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) &&
                        topic.TryGetProperty("FirstURL", out var furl))
                    {
                        results.Add(new
                        {
                            title = text.GetString()?[..Math.Min(text.GetString()!.Length, 80)] ?? "",
                            url = furl.GetString() ?? "",
                            snippet = text.GetString() ?? ""
                        });
                    }
                }
            }

            if (results.Count == 0)
            {
                results.Add(new
                {
                    title = "No instant results",
                    url = $"https://duckduckgo.com/?q={encoded}",
                    snippet = $"No instant-answer results found for '{query}'. Try a different or more specific query."
                });
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return JsonSerializer.Serialize(new[] { new { title = "Error", url = "", snippet = ex.Message } });
        }
    }

    /// <summary>Save a research note for later summarization.</summary>
    [Description("Save a research note. Use this to record important facts, quotes, or findings as you research.")]
    public static string SaveNote(
        [Description("The note text to save")] string note)
    {
        s_notes.Add(note);

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note #{s_notes.Count}: {Truncate(note, 100)}");
        Console.ResetColor();

        return $"Note #{s_notes.Count} saved.";
    }

    /// <summary>Retrieve all saved research notes.</summary>
    [Description("Retrieve all saved research notes so far.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
            return "No notes saved yet.";

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📋 Retrieving {s_notes.Count} note(s)");
        Console.ResetColor();

        return string.Join("\n", s_notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    private static string Truncate(string text, int max) =>
        text.Length <= max ? text : text[..(max - 1)] + "…";
}

// --- Main -------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return 1;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()   // auto-invoke tools
    .Build();

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔═══════════════════════════════════════════╗");
Console.WriteLine("║       🔬  AI Research Agent  🔬          ║");
Console.WriteLine("╠═══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic and the agent will search  ║");
Console.WriteLine("║  the web, take notes, and summarize.      ║");
Console.WriteLine("║  Type 'exit' to quit.                     ║");
Console.WriteLine("╚═══════════════════════════════════════════╝");
Console.ResetColor();

var tools = new[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

while (true)
{
    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.White;
    Console.Write("Enter a research topic: ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine($"\nResearching \"{topic}\"…\n");
    Console.ResetColor();

    var systemPrompt = """
        You are a research agent. Your goal is to research the given topic thoroughly.

        Workflow:
        1. Search the web for information on the topic (try 2-3 different search queries).
        2. As you discover important facts, save them as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes with GetNotes.
        4. Produce a well-structured summary with sections, key facts, and source URLs.

        Be thorough but concise. Always cite sources.
        """;

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research this topic: {topic}")
    };

    var options = new ChatOptions { Tools = [.. tools] };

    try
    {
        var response = await client.GetResponseAsync(messages, options);

        Console.ForegroundColor = ConsoleColor.Cyan;
        Console.WriteLine("\n════════════════ Research Summary ════════════════\n");
        Console.ResetColor();
        Console.WriteLine(response.Text);
        Console.ForegroundColor = ConsoleColor.Cyan;
        Console.WriteLine("\n══════════════════════════════════════════════════");
        Console.ResetColor();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");
return 0;

